'use client'

import { useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useAuth } from '@/contexts/AuthContext'
import { supabase } from '@/lib/supabase'

export default function LoginPage() {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const { signIn } = useAuth()
  const router = useRouter()

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setError('')

    try {
      const result = await signIn(email, password)

      if (result.error) {
        setError(result.error.message)
        setLoading(false)
        return
      }

      // Başarılı giriş - admin kontrolü yap
      if (!supabase) {
        setError('Supabase yapılandırılmamış. Lütfen .env.local dosyasını kontrol edin.')
        setLoading(false)
        return
      }

      const { data: { user } } = await supabase.auth.getUser()
      
      if (!user) {
        setError('Giriş başarısız. Lütfen tekrar deneyin.')
        setLoading(false)
        return
      }

      // E-posta doğrulaması kontrolü (opsiyonel - development için kapatılabilir)
      // const emailConfirmed = user.email_confirmed_at || (user as any).confirmed_at
      // if (!emailConfirmed) {
      //   setError('E-posta doğrulaması yapılmamış. Lütfen e-postanızı kontrol edin.')
      //   await supabase.auth.signOut()
      //   setLoading(false)
      //   return
      // }

      // Admin kontrolü - maybeSingle kullan (hata vermez)
      console.log('🔍 Admin kontrolü başlatılıyor...', { userId: user.id, email: user.email })
      
      const { data: adminUser, error: adminError } = await supabase
        .from('admins')
        .select('user_id, role, email')
        .eq('user_id', user.id)
        .maybeSingle()

      // Detaylı hata loglama
      if (adminError) {
        console.error('❌ Admin check error:', {
          code: adminError.code,
          message: adminError.message,
          details: adminError.details,
          hint: adminError.hint
        })
        
        // PGRST116 = No rows returned (kullanıcı admin değil - bu normal)
        if (adminError.code === 'PGRST116') {
          console.log('ℹ️ Kullanıcı admin tablosunda yok:', user.email)
          setError('Bu hesap admin yetkisine sahip değil. Lütfen admin panelinden admin yetkisi verin.')
          setLoading(false)
          setTimeout(() => {
            router.push('/')
          }, 3000)
          return
        }
        
        // Tablo yoksa - kurulum yapılmamış
        if (adminError.code === '42P01' || 
            adminError.message?.includes('relation') || 
            adminError.message?.includes('does not exist') ||
            (adminError.message?.includes('table') && adminError.message?.includes('not exist'))) {
          console.error('❌ admins tablosu bulunamadı!')
          setError('❌ Database kurulumu yapılmamış! Lütfen Supabase SQL Editor\'da SIFIRDAN_TAM_KURULUM.sql dosyasını çalıştırın.')
          setLoading(false)
          return
        }
        
        // RLS hatası
        if (adminError.code === '42501' || 
            adminError.message?.includes('permission') || 
            adminError.message?.includes('policy') ||
            adminError.message?.includes('row-level security')) {
          console.error('❌ RLS Policy hatası!')
          console.error('🔍 Hata detayları:', adminError)
          setError('❌ RLS Policy hatası. Supabase SQL Editor\'da şunu çalıştırın:\n\nSELECT * FROM admins WHERE user_id = \'' + user.id + '\';\n\nEğer sonuç boşsa, ADMIN_EKLEME_HIZLI.sql dosyasını çalıştırın.')
          setLoading(false)
          return
        }
        
        // Diğer hatalar
        console.error('❌ Bilinmeyen admin kontrol hatası:', adminError)
        setError('❌ Admin kontrolü sırasında hata: ' + (adminError.message || 'Bilinmeyen hata') + '\n\nHata kodu: ' + adminError.code)
        setLoading(false)
        return
      }

      // Admin kontrolü başarılı
      if (adminUser) {
        const role = (adminUser as any)?.role as string | undefined
        const isAllowedAdmin = role === 'admin' || role === 'super_admin' || !role
        
        console.log('✅ Admin user bulundu:', {
          email: adminUser.email || user.email,
          role: role || 'legacy',
          isAllowed: isAllowedAdmin
        })
        
        if (isAllowedAdmin) {
          console.log('✅ Admin user confirmed, redirecting to admin panel')
          setLoading(false)
          if (window.location.pathname !== '/admin') {
            window.location.href = '/admin'
          }
        } else {
          console.log('❌ User has admin record but role is not allowed:', role)
          setError('Bu hesap admin yetkisine sahip değil. Role: ' + (role || 'none'))
          setLoading(false)
          setTimeout(() => {
            router.push('/')
          }, 3000)
        }
      } else {
        console.log('❌ User is not admin (no record in admins table), redirecting to home')
        setError('Bu hesap admin yetkisine sahip değil. Lütfen admin panelinden admin yetkisi verin.')
        setLoading(false)
        setTimeout(() => {
          router.push('/')
        }, 3000)
      }
    } catch (err) {
      console.error('Login error:', err)
      setError('Bir hata oluştu. Lütfen tekrar deneyin.')
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col justify-center py-12 sm:px-6 lg:px-8">
      <div className="sm:mx-auto sm:w-full sm:max-w-md">
        <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
          DikiliHaber'a Giriş Yap
        </h2>
        <p className="mt-2 text-center text-sm text-gray-600">
          Hesabınız yok mu?{' '}
          <Link href="/auth/register" className="font-medium text-primary hover:text-blue-500">
            Kayıt olun
          </Link>
        </p>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
        <div className="bg-white py-8 px-4 shadow sm:rounded-lg sm:px-10">
          <form className="space-y-6" onSubmit={handleSubmit}>
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-gray-700">
                E-posta Adresi
              </label>
              <div className="mt-1">
                <input
                  id="email"
                  name="email"
                  type="email"
                  autoComplete="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="appearance-none block w-full px-3 py-2 border border-gray-300 rounded-md placeholder-gray-400 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm"
                />
              </div>
            </div>

            <div>
              <label htmlFor="password" className="block text-sm font-medium text-gray-700">
                Şifre
              </label>
              <div className="mt-1">
                <input
                  id="password"
                  name="password"
                  type="password"
                  autoComplete="current-password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="appearance-none block w-full px-3 py-2 border border-gray-300 rounded-md placeholder-gray-400 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm"
                />
              </div>
            </div>

            {error && (
              <div className="text-red-600 text-sm text-center">
                {error}
              </div>
            )}

            <div>
              <button
                type="submit"
                disabled={loading}
                className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-primary hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? 'Giriş yapılıyor...' : 'Giriş Yap'}
              </button>
            </div>
          </form>

          <div className="mt-6">
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-gray-300" />
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="px-2 bg-white text-gray-500">Veya</span>
              </div>
            </div>

            <div className="mt-6 text-center">
              <Link href="/" className="text-primary hover:text-blue-500">
                Ana sayfaya dön
              </Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}